#include <json.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *data = (char *)malloc(size + 1);
    fread(data, 1, size, f);
    data[size] = '\0';
    fclose(f);

    printf("Input (%ld bytes): ", size);
    for (long i = 0; i < size; i++) {
        if (data[i] >= 32 && data[i] < 127)
            putchar(data[i]);
        else
            printf("\\x%02x", (unsigned char)data[i]);
    }
    printf("\n");

    json_tokener *tok = json_tokener_new();
    json_object *obj = json_tokener_parse_ex(tok, data, size);

    printf("Error: %s\n", json_tokener_error_desc(json_tokener_get_error(tok)));
    if (obj) {
        printf("Result: %s\n", json_object_to_json_string(obj));
        json_object_put(obj);
    }

    printf("pb->buf: '%s'\n", tok->pb->buf);
    printf("pb->bpos: %d\n", tok->pb->bpos);

    json_tokener_free(tok);
    free(data);
    return 0;
}
